-- Missing DBS Masters cards patch generated from DeckPlanet API export
BEGIN TRANSACTION;
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10058, 'BT30-107', 'North Kai', 'BT30', 'Uncommon[UC]', 'LEADER', 'White', NULL, NULL, NULL, 10000, NULL, NULL, NULL, '10000', '[auto] When this card is placed in your Leader Area, activate up to 1 {Serpent Road} from your deck.
[br]
[activate main][once per turn] Switch 1 of your white energy to Hidden Mode, then place 1 white ≪King Kai''s Planet≫ card from your hand under {Serpent Road} in your Battle Area: Draw 1 card.
[br]
[awaken] If you have 2 or more Hidden Mode energy: Draw 2 cards and add cards from your life to your hand until you have 6 life left.', '<Badge variant="blue">Auto</Badge> When this card is placed in your Leader Area, activate up to 1 {Serpent Road} from your deck. <br /> <Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Switch 1 of your white energy to Hidden Mode, then place 1 white ≪King Kai''s Planet≫ card from your hand under {Serpent Road} in your Battle Area: Draw 1 card. <br /> <Badge variant="yellow">Awaken</Badge> If you have 2 or more Hidden Mode energy: Draw 2 cards and add cards from your life to your hand until you have 6 life left.', '["God","King Kai''s Planet"]', '["North Kai"]', '["Android Cell Saga"]', '[]', NULL, 0, 0, 4, 'North Kai, Ultra Teachings', '15000', '[activate main][once per turn] Switch 1 of your white energy to Hidden Mode, then place 1 white ≪King Kai''s Planet≫ card from your hand under {Serpent Road} in your Battle Area: Draw 2 cards.
[br]
[activate main][once per turn] Look at up to 7 cards from the top of your deck, place up to 1 white ≪King Kai''s Planet≫ card under {Serpent Road} in your Battle Area, then shuffle your deck.', '<Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Switch 1 of your white energy to Hidden Mode, then place 1 white ≪King Kai''s Planet≫ card from your hand under {Serpent Road} in your Battle Area: Draw 2 cards. <br /> <Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Look at up to 7 cards from the top of your deck, place up to 1 white ≪King Kai''s Planet≫ card under {Serpent Road} in your Battle Area, then shuffle your deck.', '["God","King Kai''s Planet"]', '["North Kai"]', '["Android Cell Saga"]');
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10025, 'BT30-001', 'Son Goku, Vegeta, & Trunks', 'BT30', 'Uncommon[UC]', 'LEADER', 'Red', NULL, NULL, NULL, 10000, NULL, NULL, NULL, '10000', '[auto] When this card attacks, look at up to 5 cards from the top of your deck, add up to 1 red ≪Saiyan≫ card to your hand, then shuffle your deck.
[br]
[awaken] When your life is at 4 or less or you have a total of 3 or more red ≪Saiyan≫ cards in your energy and Battle Area: Switch up to 1 of your energy to Active Mode, add up to 1 {Spirit} from your deck to your hand, shuffle your deck, and add cards from your life to your hand until you have 6 life left.', '<Badge variant="blue">Auto</Badge> When this card attacks, look at up to 5 cards from the top of your deck, add up to 1 red ≪Saiyan≫ card to your hand, then shuffle your deck. <br /> <Badge variant="yellow">Awaken</Badge> When your life is at 4 or less or you have a total of 3 or more red ≪Saiyan≫ cards in your energy and Battle Area: Switch up to 1 of your energy to Active Mode, add up to 1 {Spirit} from your deck to your hand, shuffle your deck, and add cards from your life to your hand until you have 6 life left.', '["Saiyan","Earthling"]', '["Son Goku","Vegeta","Trunks: Future"]', '["Android 13 Saga"]', '[]', NULL, 0, 0, 4, 'Super Saiyans United', '15000', '[auto][once per turn] When one of your cards is added to your Z-Energy, draw 1 card.
[br]
[auto] If you have 1 or more {Spirit} under any of the cards in your Battle Area and you place all of them at the bottom of their owner''s deck: At the end of your turn, draw 1 card.
[br]
[activate battle][once per turn] Place 1 {Spirit} from your Z-Energy at the bottom of its owner''s deck: Choose up to 1 of your cards and it gets +5000 power for the battle.', '<Badge variant="blue">Auto</Badge><Badge variant="red">Once per turn</Badge> When one of your cards is added to your Z-Energy, draw 1 card. <br /> <Badge variant="blue">Auto</Badge> If you have 1 or more {Spirit} under any of the cards in your Battle Area and you place all of them at the bottom of their owner''s deck: At the end of your turn, draw 1 card. <br /> <Badge variant="orange">Activate: Battle</Badge><Badge variant="red">Once per turn</Badge> Place 1 {Spirit} from your Z-Energy at the bottom of its owner''s deck: Choose up to 1 of your cards and it gets +5000 power for the battle.', '["Saiyan","Earthling"]', '["Son Goku","Vegeta","Trunks: Future"]', '["Android 13 Saga"]');
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (4225, 'BT8-022', 'Beerus Ball', 'BT8', 'Uncommon[UC]', 'EXTRA', 'Red', 1, NULL, NULL, NULL, '1', NULL, NULL, NULL, '[Counter: Play] If your Leader Card is red and your life is at 4 or less: If the Battle Card being played has 15000 power or less, it is placed in its owner''s Drop Area instead of being played, and if it''s your opponent''s turn, choose up to 1 of your Leader Cards and it gets +5000 power for the duration of the turn.<br>[Permanent] If you have a multicolor card in your energy and your life is at 4 or less, you can activate this card''s [Counter] skill from your hand by adding a card from your life to your hand instead of paying its energy cost.', '<Badge variant="green">Counter: Play</Badge> If your Leader Card is red and your life is at 4 or less: If the Battle Card being played has 15000 power or less, it is placed in its owner''s Drop Area instead of being played, and if it''s your opponent''s turn, choose up to 1 of your Leader Cards and it gets +5000 power for the duration of the turn.<br /><Badge variant="purple">Permanent</Badge> If you have a multicolor card in your energy and your life is at 4 or less, you can activate this card''s <Badge variant="green">Counter</Badge> skill from your hand by adding a card from your life to your hand instead of paying its energy cost.', '[]', '[]', '[]', '["Counter: Play","Permanent","Counter"]', NULL, 0, 0, 4, NULL, NULL, NULL, NULL, '[]', '[]', '[]');
