INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10043, 'BT30-044', 'Majin Buu', 'BT30', 'Uncommon[UC]', 'LEADER', 'Green', NULL, NULL, NULL, 10000, NULL, NULL, NULL, '10000', '[activate main][once per turn] Add 1 card from your hand to your Z-Energy: Draw 1 card.
[br]
[awaken] When your life is at 4 or less, or you have 2 or more energy and a green Z-Unison with a specified cost of 1 in play: Add up to 1 {Absorption} from your deck to your hand, shuffle your deck, draw 1 card, and add cards from your life to your hand until you have 6 life left.', '<Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Add 1 card from your hand to your Z-Energy: Draw 1 card. <br /> <Badge variant="yellow">Awaken</Badge> When your life is at 4 or less, or you have 2 or more energy and a green Z-Unison with a specified cost of 1 in play: Add up to 1 {Absorption} from your deck to your hand, shuffle your deck, draw 1 card, and add cards from your life to your hand until you have 6 life left.', '["Majin"]', '["Majin Buu"]', '["Majin Buu Saga"]', '[]', NULL, 0, 0, 4, 'Majin Buu, Ultimate Majin', '15000', '[auto][once per turn] When you activate [union-absorb], play 1 Majin Token in Rest Mode. ([em]Majin Tokens have 15000 power, 0 combo cost, and 5000 combo power[/em])
[br]
[auto] When this card attacks, draw 2 cards and discard 1 card from your hand.
[br]
[activate battle][once per turn] Use up to 2 cards with 5000 combo power from under your green <Majin Buu> cards in a combo with their skills negated for the turn.', '<Badge variant="blue">Auto</Badge><Badge variant="red">Once per turn</Badge> When you activate <Badge variant="red">Union Absorb</Badge>, play 1 Majin Token in Rest Mode. (<em>Majin Tokens have 15000 power, 0 combo cost, and 5000 combo power</em>) <br /> <Badge variant="blue">Auto</Badge> When this card attacks, draw 2 cards and discard 1 card from your hand. <br /> <Badge variant="orange">Activate: Battle</Badge><Badge variant="red">Once per turn</Badge> Use up to 2 cards with 5000 combo power from under your green &lt;Majin Buu&gt; cards in a combo with their skills negated for the turn.', '["Majin"]', '["Majin Buu"]', '["Majin Buu Saga"]');
