INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10026, 'BT30-002', 'Fusion Android 13, Hatred Endgame', 'BT30', 'Super Rare[SR]', 'Z-UNISON', 'Red', NULL, NULL, NULL, 20000, 'X', NULL, NULL, '20000', '[blocker]
[br]
[auto] When this card attacks, add 1 marker to it, then choose up to 1 of your opponent''s Battle Cards with 15000 power or less, ignoring [barrier], and KO it.
[br]
[0][activate main] Switch this card to Active Mode.
[br]
[-4][activate main/battle] Choose all of your opponent''s Battle Cards and they get -20000 power for the turn.', '<Badge variant="red">Blocker</Badge> <br /> <Badge variant="blue">Auto</Badge> When this card attacks, add 1 marker to it, then choose up to 1 of your opponent''s Battle Cards with 15000 power or less, ignoring <Badge variant="red">Barrier</Badge>, and KO it. <br /> <img src="../../images/cardlist/common/UNISON_plus-minus_00.png" alt="0" class="skillText"><Badge variant="orange">Activate: Main</Badge> Switch this card to Active Mode. <br /> <img src="../../images/cardlist/common/UNISON_minus_04.png" alt="-4" class="skillText"><Badge variant="orange">Activate: Main/Battle</Badge> Choose all of your opponent''s Battle Cards and they get -20000 power for the turn.', '[]', '[]', '[]', '[]', '2', 0, 0, 4, NULL, NULL, NULL, NULL, '[]', '[]', '[]');
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10059, 'BT30-108', 'Son Goku, Pan, & Trunks', 'BT30', 'Uncommon[UC]', 'LEADER', 'White', NULL, NULL, NULL, 10000, NULL, NULL, NULL, '10000', '[activate main][once per turn] Add 1 card from your life to your hand: Look at up to 5 cards from the top of your deck, add up to 1 white ≪Saiyan≫ card to your hand, then shuffle your deck.
[br]
[awaken] When your life is at 5 or less: Draw 1 card, then switch up to 1 of your energy to Active Mode.', '<Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Add 1 card from your life to your hand: Look at up to 5 cards from the top of your deck, add up to 1 white ≪Saiyan≫ card to your hand, then shuffle your deck. <br /> <Badge variant="yellow">Awaken</Badge> When your life is at 5 or less: Draw 1 card, then switch up to 1 of your energy to Active Mode.', '["Saiyan","Earthling"]', '["Son Goku: GT","Pan","Trunks: GT"]', '["Black Star Dragon Ball Saga"]', '[]', NULL, 0, 0, 4, 'Son Goku, Pan, & Trunks, Exciting Adventures', '15000', '[auto] when this card attacks, draw 1 card.
[br]
[activate main/battle][once per turn] Choose 1 of your cards and switch it to Revealed Mode: Choose up to 1 of your white <Son Goku: GT>, <Pan>, or <Trunks: GT> Battle Cards, switch it to Active Mode, and it gets +5000 power for the turn.
[br]
[activate main][once per turn] Play up to 1 <Son Goku: GT>, <Pan>, or <Trunks: GT> card -- all white and with 4000 power -- from your hand.', '<Badge variant="blue">Auto</Badge> when this card attacks, draw 1 card. <br /> <Badge variant="orange">Activate: Main/Battle</Badge><Badge variant="red">Once per turn</Badge> Choose 1 of your cards and switch it to Revealed Mode: Choose up to 1 of your white &lt;Son Goku: GT&gt;, &lt;Pan&gt;, or &lt;Trunks: GT&gt; Battle Cards, switch it to Active Mode, and it gets +5000 power for the turn. <br /> <Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Play up to 1 &lt;Son Goku: GT&gt;, &lt;Pan&gt;, or &lt;Trunks: GT&gt; card -- all white and with 4000 power -- from your hand.', '["Saiyan","Earthling"]', '["Son Goku: GT","Pan","Trunks: GT"]', '["Black Star Dragon Ball Saga"]');
