er"]', '3', 0, 0, 7, NULL, NULL, NULL, NULL, '[]', '[]', '[]');
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10040, 'BT30-016', 'Bulma', 'BT30', 'Uncommon[UC]', 'LEADER', 'Blue', NULL, NULL, NULL, 5000, NULL, NULL, NULL, '5000', '[permanent] You can''t include non-≪Earthling≫ Battle Cards in your deck.
[br]
[activate main][once per turn] Draw 1 card and add up to 1 card from your life to your hand.
[br]
[awaken] When your life is at 6 or less: Draw 1 card, and you can''t activate skills on cards with an energy cost of 4 or more in any of your areas for the game.', '<Badge variant="purple">Permanent</Badge> You can''t include non-≪Earthling≫ Battle Cards in your deck. <br /> <Badge variant="orange">Activate: Main</Badge><Badge variant="red">Once per turn</Badge> Draw 1 card and add up to 1 card from your life to your hand. <br /> <Badge variant="yellow">Awaken</Badge> When your life is at 6 or less: Draw 1 card, and you can''t activate skills on cards with an energy cost of 4 or more in any of your areas for the game.', '["Earthling"]', '["Bulma"]', '["Young Son Goku Saga"]', '[]', NULL, 0, 0, 4, 'Bulma, Adventurous Bunny Girl', '10000', '[permanent] If you have 7 or less energy and your blue ≪Earthling≫ card would be removed from a Battle Area by a skill or KO''d, add that card to your energy in Rest Mode instead.
[br]
[auto][once per turn] When you blue ≪Earthling≫ card attacks, draw 1 card.
[br]
[activate battle] Place 1 of your blue energy at the bottom of its owner''s deck: Choose up to 1 of your blue ≪Earthling≫ cards and it gets +15000 power for the battle.', '<Badge variant="purple">Permanent</Badge> If you have 7 or less energy and your blue ≪Earthling≫ card would be removed from a Battle Area by a skill or KO''d, add that card to your energy in Rest Mode instead. <br /> <Badge variant="blue">Auto</Badge><Badge variant="red">Once per turn</Badge> When you blue ≪Earthling≫ card attacks, draw 1 card. <br /> <Badge variant="orange">Activate: Battle</Badge> Place 1 of your blue energy at the bottom of its owner''s deck: Choose up to 1 of your blue ≪Earthling≫ cards and it gets +15000 power for the battle.', '["Earthling"]', '["Bulma"]', '["Young Son Goku Saga"]');
