INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (10035, 'BT30-011', 'Trunks, Saiyans Assembled', 'BT30', 'Common[C]', 'BATTLE', 'Red', 1, 0, 5000, 4000, '1', '0', '5000', '4000', '[auto] When this card is played, look at up to 5 cards from the top of your deck, add up to 1 red ≪Saiyan≫ card with an energy cost of 4 or less to your hand, then shuffle your deck.
[br]
[activate main] If your Leader''s back side is {Super Saiyans United} and you add this card to your Z-Energy: Place up to 1 {Spirit} from your deck into its owner''s Drop, then shuffle your deck.', '<Badge variant="blue">Auto</Badge> When this card is played, look at up to 5 cards from the top of your deck, add up to 1 red ≪Saiyan≫ card with an energy cost of 4 or less to your hand, then shuffle your deck. <br /> <Badge variant="orange">Activate: Main</Badge> If your Leader''s back side is {Super Saiyans United} and you add this card to your Z-Energy: Place up to 1 {Spirit} from your deck into its owner''s Drop, then shuffle your deck.', '["Saiyan","Earthling"]', '["Trunks: Future"]', '["Android 13 Saga"]', '[]', NULL, 0, 0, 4, NULL, NULL, NULL, NULL, '[]', '[]', '[]');
INSERT OR REPLACE INTO cards (id, card_number, card_name, card_series, card_rarity, card_type, card_color, energy_cost_int, combo_cost_int, combo_power_int, power_int, card_energy_cost, card_combo_cost, card_combo_power, card_power, card_skill_unstyled, card_skill_html, card_traits_json, card_character_json, card_era_json, keywords_json, z_energy_cost, is_banned, is_limited, limited_to, card_back_name, card_back_power, card_back_skill_unstyled, card_back_skill_html, card_back_traits_json, card_back_character_json, card_back_era_json) VALUES (7358, 'BT10-088', 'Dormant Potential Unleashed', 'BT10', 'Super Rare[SR]', 'EXTRA', 'Green', 1, NULL, NULL, NULL, '1', NULL, NULL, NULL, '[Counter: Attack] If your Leader Card is mono-green: Choose any number of your opponent''s Battle Cards that add up to a total energy cost of 2 or less and KO them. Additionally, you may choose 1 green card in your hand and discard it. If you do, your opponent can only attack once more this turn.<br>[Permanent] If you have a green Unison Card in play, you can activate this card''s [Counter] skill from your hand without paying its energy cost.', '<Badge variant="green">Counter: Attack</Badge> If your Leader Card is mono-green: Choose any number of your opponent''s Battle Cards that add up to a total energy cost of 2 or less and KO them. Additionally, you may choose 1 green card in your hand and discard it. If you do, your opponent can only attack once more this turn.<br /><Badge variant="purple">Permanent</Badge> If you have a green Unison Card in play, you can activate this card''s <Badge variant="green">Counter</Badge> skill from your hand without paying its energy cost.', '[]', '[]', '[]', '["Counter: Attack","Permanent","Counter"]', NULL, 0, 0, 4, NULL, NULL, NULL, NULL, '[]', '[]', '[]');
